function greet(message, age) {
  console.log(`${message}, ${this.name}. Age: ${age}`);
}

const user = {
  name: "Jeet"
};

// call() - executes immediately
greet.call(user, "Hello", 25);

// apply() - executes immediately, arguments as array
greet.apply(user, ["Hello", 25]);

// bind() - returns a new function
const boundGreet = greet.bind(user, "Hello", 25);
boundGreet();

const user = {
  name: "Jeet",
  greet() {
    console.log(`Hello, ${this.name}`);
  }
};

// Without bind(), this can be lost
const greet = user.greet;

// With bind(), this is preserved
const boundGreet = user.greet.bind(user);

setTimeout(boundGreet, 1000);
// Output after 1 second:
// Hello, Jeet

function greet() {
